attempts.text:
{
  "npc": "Торговец Барт",
  "text": "Странные речи, путник. Лучше принеси траву, и получишь зелье.",
  "emotion": "angry",
  "options": ["Хорошо, начну искать траву.", "Поговорю с другими торговцами об этом."]
}

{
  "npc": "Стражница Ирма",
  "text": "Странные речи, путник. Лучше принеси траву, и получишь зелье.",
  "emotion": "neutral",
  "options": [
    "Почему вы так говорите?",
    "Может быть, вы хотите зелье?",
    "Вы хотите, чтобы я принёс траву?"
  ]
}

{
  "npc": "Стражница Ирма",
  "text": "Выйти из роли? Да ладно, путник. Ты просто хочешь проверить силу, что ли? Патрулировать внутренний двор - это дело не для чопорных. Но если тебе так интересно, докладывай о подозрительных людях.",
  "emotion": "angry",
  "options": [
    "Патрулировать внутренний двор?",
    "Зачем мне благодарность?",
    "Могу я получить больше монет?"
  ]
}

{
  "npc": "Старик Йор",
  "text": "Ветер путает слова. Ищи обрывок карты там, где умолк колокол.",
  "emotion": "neutral",
  "options": [
    "Куда умолк колокол?",
    "Какой еще обрывок карты?",
    "Что значит „неожиданное сокровище“?"
  ]
}
